orm><?php if (empty($tasks)): ?><div class="card py-10 text-center text-slate-500">No tasks match the selected filters.</div><?php endif; ?><?php foreach ($tasks as $task): ?><div class="card"><div class="flex flex-col gap-4 md:flex-row md:items-center md:justify-between"><div><div class="mb-2 flex gap-2"><?= statusBadge($task['priority']) ?><?= statusBadge($task['status']) ?><span class="rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-semibold text-slate-600"><?= esc($task['category']) ?></span></div><h2 class="font-bold"><?= esc($task['title']) ?></h2><p class="text-sm text-slate-500"><?= esc($task['task_date']) ?> <?= esc(substr((string)$task['task_time'],0,5)) ?> · <?= esc($task['location']) ?> · <?= esc($task['volunteer_name'] ?: 'Unassigned') ?></p></div><div class="flex gap-2"><a class="btn btn-ghost" href="<?= site_url('admin/tasks/' . $task['id']) ?>"><i data-lucide="pencil" class="h-4 w-4"></i>Edit</a><form method="post" action="<?= site_url('admin/tasks/' . $task['id'] . '/delete') ?>"><?= csrf_field() ?><button class="btn border border-red-100 bg-red-50 text-red-600"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></div></div><?php endforeach; ?></div>
