SON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT), 'attr'); ?><button type="button" @click='selectedTask = <?= $calendarTask ?>' class="block w-full rounded-xl border-l-4 border-rescue-600 bg-rescue-50 p-3 text-left shadow-sm transition hover:bg-rescue-100 hover:shadow"><p class="text-xs font-bold text-rescue-700"><?= esc(date('g:i A', strtotime($task['task_time']))) ?></p><p class="mt-1 text-sm font-bold text-slate-900"><?= esc($task['title']) ?></p><p class="mt-1 truncate text-xs text-slate-600"><i data-lucide="user" class="mr-1 inline h-3 w-3"></i><?= esc($task['volunteer_name'] ?: 'Unassigned') ?></p></button><?php endforeach; ?></div></div><?php endforeach; ?></div></div></div>
